        }

        std::string result;
        result.reserve(total_length);

        result += '[';
        for (size_t i = 0; i < input_length; ++i) {
            if (i > 0) {
                result += ", ";
            }

            int value = input[i];
            char buffer[32];
            auto [ptr, ec] = std::to_chars(buffer, buffer + sizeof(buffer), value);
            result.append(buffer, ptr);
        }
        result += ']';

        return copy_to_c_string(result);
    } catch (...) {
        return nullptr;
    }
}

